let embeddedRule0218: RuleEntry = RuleEntry(
    id: "phb_ch06_starting_money",
    book: "PHB",
    chapterNumber: 6,
    chapterTitle: "Money and Equipment",
    breadcrumbs: "Player's Handbook > Chapter 6: Money and Equipment > Starting Money",
    topic: "Starting Money",
    ruleType: "core_rule",
    summary: "All player characters begin with some amount of cash. This nest egg may be your character's life savings. It may be a gift from his parents to start him out in the world. It may be his booty from an army campaign.",
    content: "All player characters begin with some amount of cash. This nest egg may be your character's life savings. It may be a gift from his parents to start him out in the world. It may be his booty from an army campaign. Perhaps he stumbled across a small treasure chest, whetting his appetite for greater and more dangerous prizes. How he came by his money is not important (although it may be fun to know). You are free to create any explanation you want.\n\nTo learn your character's starting funds, roll the dice indicated for his group in the following table.\n\n[TABLE_REF: Table 43: Initial Character Funds]\n\n:** -Priest characters can use their money only to purchase equipment and goods. Once all purchases are made, the priest character must return all but two or three of his remaining gold pieces to his superiors (since his equipment is supplied by his organization). Priests cannot lend any of their initial funds to other characters.*\n\nThis is the number of gold pieces your character has to obtain equipment. If you are creating a character starting out at a level above 1st level, check with the DM to see if you can increase your character's funds beyond the amounts given here.\nMulti-class characters use the most advantageous die range of their classes.",
    tables: [
        RuleTable(
                tableNumber: "Table 43",
                title: "Table 43: Initial Character Funds",
                headers: ["Class", "Starting Gold"],
                rows: [
                    ["Cleric*", "3d6 × 10 gp"],
                    ["Rogue", "2d6 × 10 gp"],
                    ["Warrior", "5d4 × 10 gp"],
                    ["Wizard", "(1d4+1) × 10 gp"]
                ]
            )
    ],
    relatedRuleIds: [],
    relatedSpells: [],
    relatedMagicItems: [],
    searchKeywords: ["money", "starting", "starting money"]
)

